import React, { useEffect } from 'react';
import { useLocation } from 'react-router-dom';
import './googlemap.css';

const Map = () => {
    const location = useLocation();
    const { lat, lng } = location.state || {};

    useEffect(() => {
        const initMap = () => {
            if (window.google && window.google.maps) {
                const defaultLocation = { lat: 0, lng: 0 };
                const mapLocation = lat && lng ? { lat, lng } : defaultLocation;

                const map = new window.google.maps.Map(document.getElementById('map'), {
                    zoom: 12,
                    center: mapLocation
                });

                if (lat && lng) {
                    new window.google.maps.Marker({
                        position: mapLocation,
                        map: map,
                        title: 'Pet Location'
                    });
                }
            } else {
                console.error("Google Maps API failed to load.");
            }
        };

        const loadScript = () => {
            const existingScript = document.getElementById('googleMaps');
            if (!existingScript) {
                const script = document.createElement('script');
                script.src = `https://maps.googleapis.com/maps/api/js?key=AIzaSyAyCujJ188OdhtBjKLmV2CheQgDnqEa-9o&callback=initMap`;
                script.id = 'googleMaps';
                script.async = true;
                script.defer = true;
                script.onload = initMap;
                document.head.appendChild(script);
            } else {
                initMap();
            }
        };

        loadScript();

        return () => {
            const script = document.getElementById('googleMaps');
            if (script) {
                document.head.removeChild(script);
            }
        };
    }, [lat, lng]);

    return (
        <div className="container">
            <div id="map" style={{ height: '400px', width: '100%' }}></div>
        </div>
    );
};

export default Map;
